 $q=$pdo->prepare('SELECT method,COALESCE(SUM(amount),0) total,COUNT(*) payment_count FROM payments WHERE paid_at>=? AND paid_at<? GROUP BY method ORDER BY total DESC');$q->execute([$start,$end]);$report['methods']=$q->fetchAll();
 $q=$pdo->prepare("SELECT oi.product_name,SUM(oi.quantity) quantity,SUM(oi.quantity*oi.unit_price) gross FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.created_at>=? AND o.created_at<? AND oi.status='active' GROUP BY oi.product_name ORDER BY quantity DESC,gross DESC LIMIT 20");$q->execute([$start,$end]);$report['products']=$q->fetchAll();
 $q=$pdo->prepare("SELECT COALESCE(s.name,'Silinmiş personel') staff_name,COUNT(DISTINCT o.session_id) session_count,SUM(CASE WHEN oi.status='active' THEN oi.quantity*oi.unit_price ELSE 0 END) gross,SUM(CASE WHEN oi.status='active' THEN oi.quantity ELSE 0 END) item_quantity FROM orders o LEFT JOIN staff_users s ON s.id=o.staff_id LEFT JOIN order_items oi ON oi.order_id=o.id WHERE o.created_at>=? AND o.created_at<? GROUP BY o.staff_id,s.name ORDER BY gross DESC");$q->execute([$start,$end]);$report['staff']=$q->fetchAll();
 $q=$pdo->prepare('SELECT HOUR(paid_at) hour_no,SUM(amount) total,COUNT(*) payment_count FROM payments WHERE paid_at>=? AND paid_at<? GROUP BY HOUR(paid_at) ORDER BY hour_no');$q->execute([$start,$end]);$report['hours']=$q->fetchAll();
 $q=$pdo->prepare('SELECT DATE(paid_at) day_date,SUM(amount) total,COUNT(DISTINCT table_session_id) ticket_count FROM payments WHERE paid_at>=? AND paid_at<? GROUP BY DATE(paid_at) ORDER BY day_date');$q->execute([$start,$end]);$report['days']=$q->fetchAll();
 $report['from']=$from;$report['to']=$to;
}
